import { mkdir, rm } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";

export interface StoredObject {
  sizeBytes: number;
  sha256: string;
}

export class StoreError extends Error {
  constructor(public readonly code: "too_large" | "invalid_key") {
    super(code);
  }
}

/**
 * Where private bytes live. Keys are generated by the API and never accepted
 * from a client, so an adapter only has to keep them opaque and school-prefixed.
 */
export interface FileStore {
  write(
    key: string,
    body: ReadableStream<Uint8Array>,
    limit: number,
  ): Promise<StoredObject>;
  open(key: string): Promise<ReadableStream<Uint8Array> | null>;
  remove(key: string): Promise<void>;
}

const KEY = /^[0-9a-f-]{36}\/[0-9a-f-]{36}$/;

export class DiskFileStore implements FileStore {
  private readonly root: string;

  constructor(root: string) {
    this.root = resolve(root);
  }

  private path(key: string) {
    if (!KEY.test(key)) throw new StoreError("invalid_key");
    return join(this.root, key);
  }

  async write(
    key: string,
    body: ReadableStream<Uint8Array>,
    limit: number,
  ): Promise<StoredObject> {
    const path = this.path(key);
    await mkdir(dirname(path), { recursive: true });
    const sink = Bun.file(path).writer();
    const hasher = new Bun.CryptoHasher("sha256");
    let sizeBytes = 0;
    try {
      for await (const chunk of body) {
        sizeBytes += chunk.byteLength;
        if (sizeBytes > limit) throw new StoreError("too_large");
        hasher.update(chunk);
        await sink.write(chunk);
      }
      await sink.end();
    } catch (error) {
      await sink.end();
      await rm(path, { force: true });
      throw error;
    }
    return { sizeBytes, sha256: hasher.digest("hex") };
  }

  async open(key: string) {
    const file = Bun.file(this.path(key));
    if (!(await file.exists())) return null;
    return file.stream();
  }

  async remove(key: string) {
    await rm(this.path(key), { force: true });
  }
}

/** Up to `limit` leading bytes of a stored object, without reading the rest. */
export async function readPrefix(
  store: FileStore,
  key: string,
  limit: number,
): Promise<Uint8Array> {
  const body = await store.open(key);
  if (!body) return new Uint8Array(0);
  const reader = body.getReader();
  const parts: Uint8Array[] = [];
  let length = 0;
  try {
    while (length < limit) {
      const { done, value } = await reader.read();
      if (done) break;
      parts.push(value);
      length += value.byteLength;
    }
  } finally {
    await reader.cancel();
  }
  const bytes = new Uint8Array(Math.min(length, limit));
  let offset = 0;
  for (const part of parts) {
    const slice = part.subarray(0, bytes.length - offset);
    bytes.set(slice, offset);
    offset += slice.byteLength;
    if (offset >= bytes.length) break;
  }
  return bytes;
}
